Translate("ruRU", "western-plaguelands", {
	title = "Западные Чумные земли",
	aliases = { "Западные Чумные земли" },
	sections = {
		{
			title = "Обзор",
			text = [=[Западные Чумные земли некогда были северным сердцем {link:lordaeron}Лордерона{/link}: краем пологих пашен, садов, житниц и богатых городков между {link:tirisfal-glades}Тирисфальскими лесами{/link} и рекой, что течет на восток. Ныне это серая, отравленная земля. Трава иссохла, деревья стоят голые, а поля, кормившие целое королевство, теперь кормят одну лишь {link:scourge}Плеть{/link}. Огромные котлы выдыхают чуму в воздух над старыми хуторами. Мертвецы ходят по дорогам. И все же край потерян не до конца. Три силы пришли оспаривать его у мертвых: {link:alliance}Альянс{/link} с юга, {link:forsaken}Отрекшиеся{/link} с запада и {link:scarlet-crusade}Алый орден{/link} из своей твердыни на севере. Ни одна из них не доверяет другим.]=],
		},
		{
			title = "Истоки",
			text = [=[Ни одна летопись не называет года, когда эти земли были впервые заселены. Они принадлежали королевству {link:lordaeron}Лордерон{/link}, пока стояло само королевство, и были в числе богатейших его владений. Город {link:ruins-of-andorhal}Андорал{/link} собирал урожаи севера в свои житницы. Городок {link:hearthglen}Дольный Очаг{/link} и Крепость Марденхольд стерегли северные холмы, и в годы после {link:second-war}Второй войны{/link} ими правил {link:tirion-fordring}Тирион Фордринг{/link}, лорд и паладин Серебряной Длани. На юге семья Баровых владела островным замком {link:caer-darrow}Каэр Дарроу{/link} на тихом озере, и знать королевства ездила туда отдыхать и заказывать свои портреты у воды.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:scourge}Плеть{/link} по-прежнему властвует над Западными Чумными землями. Лич {link:araj-the-summoner}Арадж Призыватель{/link} удерживает {link:ruins-of-andorhal}Руины Андорала{/link}. Четыре чумных котла, за которыми смотрят повелители котлов, отравляют пашни. На юге, под {link:caer-darrow}Каэр Дарроу{/link}, культ обучает своих некромантов в Некроситете.

Против них на окраинах края стоят малые силы. В Лагере Промозглого Ветра на юге командир {link:commander-ashlam-valorfist}Ашлам Кулак Доблести{/link} собирает солдат и защитников {link:alliance}Альянс{/link}а под знаменем {link:kingdom-of-stormwind}королевства Штормград{/link}. В {link:the-bulwark}Бастион{/link}е на западе верховный исполнитель {link:high-executor-derrington}Деррингтон{/link} держит восточные врата {link:tirisfal-glades}Тирисфаль{/link}ских лесов для Отрекшихся и {link:horde}Орды{/link}. На севере {link:scarlet-crusade}Алый орден{/link} удерживает {link:hearthglen}Дольный Очаг{/link} под началом верховного лорда {link:taelan-fordring}Телан{/link}а Фордринга. Орден сражается с Плетью — и со всеми прочими тоже. Посланцы {link:argent-dawn}Серебряного Рассвета{/link} служат в лагерях и Альянса, и Орды и не просят у обоих ничего, кроме войны с мертвыми.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}{link:scourge}Плеть{/link}.{/b} Скелеты, вурдалаки, поганища, призраки и неупокоенные духи утопленников и убитых. Они держат {link:ruins-of-andorhal}Андорал{/link}, {link:sorrow-hill}Холм Печали{/link} и старые фермы.
• {b}{link:cult-of-the-damned}Культ Проклятых{/link}.{/b} Живые слуги Короля-лича, которые трудятся среди мертвых — в Андорале и в Некроситете.
• {b}{link:alliance}Альянс{/link}.{/b} Солдаты {link:stormwind-city}Штормград{/link}а, жрецы, алхимики и агенты {link:si-7}SI:7{/link} в Лагере Промозглого Ветра.
• {b}{link:forsaken}Отрекшиеся{/link}.{/b} Гарнизон {link:the-bulwark}Бастион{/link}а, который держит границу для Темной Госпожи.
• {b}{link:scarlet-crusade}Алый орден{/link}.{/b} Рыцари, жрецы и инквизиторы Дольного Очага и работники лесопилки, захваченной ими на Северном Кряже.
• {b}{link:argent-dawn}Серебряный Рассвет{/link}.{/b} Офицеры и защитники, размещенные в обоих лагерях.
• {b}Неупокоенные мертвецы старого королевства.{/b} Призраки, никогда не принадлежавшие Плети: духи {link:caer-darrow}Каэр Дарроу{/link}, женщина с Поля {link:janice-felstone}Джанис{/link}, скорбящие Холма Печали.
• {b}Зачумленные звери.{/b} Волки, медведи, летучие мыши и стервятники, больные той же чумой, что и сама земля.]=],
		},
		{
			title = "История",
			text = [=[• {b}Королевство.{/b} Многие поколения здесь лежали пашни и речные городки {link:lordaeron}Лордерон{/link}а, богатые и мирные под защитой силы королевства.
• {b}{link:second-war}Вторая война{/link}.{/b} Когда орочья {link:horde}Орда{/link} вторглась на север, рыцари Серебряной Длани выступили против нее. Среди них был и {link:tirion-fordring}Тирион Фордринг{/link}. После войны он правил землями вокруг Дольного Очага, пока не лишился их за то, что пощадил жизнь {link:orcs}орк{/link}а.
• {b}Чума.{/b} Перед {link:third-war}Третьей войной{/link} посланцы {link:cult-of-the-damned}Культа Проклятых{/link} отравили зерно в житницах {link:ruins-of-andorhal}Андорал{/link}а, и это зерно разошлось по деревням севера. Те, кто ел его, заболевали, умирали и восставали вновь слугами Короля-лича. Принц {link:arthas-menethil}Артас Менетил{/link} пришел в Андорал и сразил главу культа {link:kel-thuzad}Кел'Тузада{/link}, но чума уже разошлась так, что исцелить ее было нельзя, и север пал — город за городом.
• {b}{link:fall-of-lordaeron}Падение Лордерона{/link}.{/b} После того как принц Артас убил своего отца, Серебряная Длань была сломлена. {link:uther-the-lightbringer}Утер Светоносный{/link} погиб от руки своего ученика, и в этих землях в память о нем возвели гробницу. Семья Баровых из {link:caer-darrow}Каэр Дарроу{/link} отдала свой замок культу, и в его склепах был основан Некроситет.
• {b}Наши дни.{/b} {link:scourge}Плеть{/link} держит сердце края. Живые цепляются за его окраины, а {link:scarlet-crusade}Алый орден{/link} удерживает север.]=],
		},
		{
			title = "Предания Чумных земель",
			text = [=[• Все карманные часы {link:ruins-of-andorhal}Андорал{/link}а и большие часы на развалинах его ратуши остановились в один и тот же час. Это был час, когда чума впервые овладела городом.
• Говорят, что на острове {link:caer-darrow}Каэр Дарроу{/link} призраки горожан вновь и вновь проживают свой последний счастливый день, словно с ними ничего не случилось.
• И {link:forsaken}Отрекшиеся{/link}, и {link:alliance}Альянс{/link} твердят, что возьмут Андорал. Ни те, ни другие не говорят, что станут делать с городом, когда он будет взят.
• Среди мертвых Холма Печали лежат многие из тех, кто пал, защищая {link:darrowshire}Дарроушир{/link} на востоке.]=],
		},
	},
})

Translate("ruRU", "chillwind-camp", {
	title = "Лагерь Промозглого Ветра",
	sections = {
		{
			title = "Обзор",
			text = [=[Лагерь Промозглого Ветра — опорный пункт {link:alliance}Альянс{/link}а в Западных Чумных землях. Он стоит на южном краю этой земли, над высотами {link:alterac-mountains}Альтеракских гор{/link}, где к склону холма жмутся несколько палаток, кузница и насест грифонов. Отсюда командир {link:commander-ashlam-valorfist}Ашлам Кулак Доблести{/link} ведет войну против {link:ruins-of-andorhal}Андорал{/link}а от имени {link:kingdom-of-stormwind}Штормграда{/link}. Его жрецы изучают чуму, его алхимик изучает Некроситет, а агент {link:si-7}SI:7{/link} ждет вестей с востока. Офицеры {link:argent-dawn}Серебряного Рассвета{/link} держат среди них свой пост. Здесь же, под защитой лагеря, живет {link:weldon-barov}Велдон Баров{/link}, последний живой лорд своего дома.]=],
		},
	},
})

Translate("ruRU", "the-bulwark", {
	title = "Бастион",
	aliases = { "Бастион" },
	sections = {
		{
			title = "Обзор",
			text = [=[Бастион — это укрепленные врата между {link:tirisfal-glades}Тирисфальскими лесами{/link} и Чумными землями. Его стену и башни возвели, чтобы не пустить {link:scourge}Плеть{/link} в земли {link:forsaken}Отрекшихся{/link}, и ныне именно Отрекшиеся несут на них стражу. Здесь командует верховный исполнитель {link:high-executor-derrington}Деррингтон{/link}. Из Бастиона он шлет своих солдат на восток — против {link:ruins-of-andorhal}Андорал{/link}а и чумных котлов, и на север — против {link:scarlet-crusade}Алого ордена{/link}. Рядом с его солдатами трудятся аптекари и жрецы Тьмы. {link:argent-dawn}Серебряный Рассвет{/link} тоже держит у врат своих офицеров. Здесь же обретается {link:alexi-barov}Алекси Баров{/link}, лорд павшего дома из числа Отрекшихся, который ждет вестей о состоянии своей семьи.]=],
		},
	},
})

Translate("ruRU", "ruins-of-andorhal", {
	title = "Руины Андорала",
	aliases = { "Андорал" },
	sections = {
		{
			title = "Обзор",
			text = [=[Андорал был великим городом-житницей северного {link:lordaeron}Лордерона{/link}. В его амбарах хранились урожаи королевства, и из них {link:cult-of-the-damned}Культ Проклятых{/link} разослал отравленное зерно, с которого началась чума. Здесь принц {link:arthas-menethil}Артас Менетил{/link} настиг и сразил главу культа {link:kel-thuzad}Кел'Тузада{/link}. Теперь город лежит в руинах, и держит его {link:scourge}Плеть{/link}. Четыре сторожевые башни стерегут подступы к нему, а в сердце города правит лич {link:araj-the-summoner}Арадж Призыватель{/link}. Все часы в Андорале остановились в тот час, когда им овладела чума. В разрушенной таверне в северо-западном углу города поселилась странная {link:gnomes}гном{/link}ка {link:chromie}Хроми{/link}.]=],
		},
	},
})

Translate("ruRU", "hearthglen", {
	title = "Дольный Очаг",
	sections = {
		{
			title = "Обзор",
			text = [=[Дольный Очаг стоит в холмах дальнего севера и смотрит сверху на Чумные земли. Это был город, где жил {link:tirion-fordring}Тирион Фордринг{/link}: он правил этими землями из Крепости Марденхольд, пока не был изгнан. В войне с {link:scourge}Плетью{/link} принц {link:arthas-menethil}Артас Менетил{/link} удерживал Дольный Очаг против мертвых, пока ему на выручку не пришел {link:uther-the-lightbringer}Утер{/link}. Сегодня город принадлежит {link:scarlet-crusade}Алому ордену{/link}. По его стенам ходят дозором воины ордена, в его крепости пребывает {link:taelan-fordring}верховный лорд Телан Фордринг{/link}, а за дорогой к нему следят с застав вдоль перевала Дольного Очага. Орден ревниво стережет город. Кое-кто в {link:stormwind-city}Штормград{/link}е полагает, что он важен не одной только своей историей.]=],
		},
	},
})

Translate("ruRU", "northridge-lumber-camp", {
	title = "Лесопилка Северного Кряжа",
	aliases = { "Лесопилка Северного Кряжа" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лесопилка Северного Кряжа лежит к югу от Дольного Очага, к западу от дороги, что поднимается к городу. До чумы это была лесопилка, где семьи севера зарабатывали свой хлеб, валя и распиливая лес с холмов. Ее захватил {link:scarlet-crusade}Алый орден{/link}. Теперь работники и лесорубы ордена под присмотром своих бригадиров рубят лес для стен Дольного Очага. Сыновья тех семей, что когда-то трудились здесь, ничего не забыли. Один служит {link:alliance}Альянс{/link}у в Лагере Промозглого Ветра, другой — {link:forsaken}Отрекшимся{/link} в {link:the-bulwark}Бастион{/link}е, и оба хотят, чтобы лесопилка была разорена, а не оставалась в руках ордена.]=],
		},
	},
})

Translate("ruRU", "felstone-field", {
	title = "Поле Джанис",
	sections = {
		{
			title = "Обзор",
			text = [=[Поле Джанис было фермой семьи Фелстоунов к северо-западу от {link:ruins-of-andorhal}Андорал{/link}а. Ее дом все еще стоит, стоит и амбар, но поля ее теперь служат {link:scourge}Плети{/link}. Среди них высится чумной котел, за которым смотрят повелитель котла Желчная Пасть и самые неопытные из мертвецов. В верхней комнате фермерского дома задержался призрак {link:janice-felstone}Джанис Фелстоун{/link}. Она не знает, как долго ждет там. Она говорит о посылке, которую собиралась отправить, и о своем муже Джоне — так, будто чума пришла лишь вчера.]=],
		},
	},
})

Translate("ruRU", "dalson-s-tears", {
	title = "Слезы Далсона",
	sections = {
		{
			title = "Обзор",
			text = [=[Слезы Далсона лежат почти точно к северу от {link:ruins-of-andorhal}Андорал{/link}а. Это была ферма семьи Далсонов, а имя, которое она носит теперь, ей дали после чумы. На ее поле стоит котел {link:scourge}Плети{/link}. В фермерском доме лежит дневник, раскрытый на последней странице, стоит шкаф, исцарапанный в отчаянии чьими-то руками, а во дворе — уборная, дверь которой избита изнутри. По двору бродит скелет. История, которую рассказывают эти вещи, — одна из самых печальных в Чумных землях.]=],
		},
	},
})

Translate("ruRU", "the-writhing-haunt", {
	title = "Удел Страданий",
	aliases = { "Удел Страданий" },
	sections = {
		{
			title = "Обзор",
			text = [=[Удел Страданий — разоренный хутор к востоку от {link:ruins-of-andorhal}Андорал{/link}а, близ разбитых стен города. {link:scourge}Плеть{/link} воздвигла здесь один из своих чумных котлов, и земля вокруг него кишит мертвецами. В хижине на ферме лежит друид-{link:tauren}таурен{/link}, который пришел издалека, чтобы исцелить зверей этого края. Лекарства он не нашел и сам заразился чумой.]=],
		},
	},
})

Translate("ruRU", "gahrron-s-withering", {
	title = "Пустошь Гаррона",
	sections = {
		{
			title = "Обзор",
			text = [=[Пустошь Гаррона — мертвая ферма на северо-востоке Западных Чумных земель, у границы {link:eastern-plaguelands}Восточных Чумных земель{/link}. Здесь стоит последний из четырех западных котлов. Его стерегут призраки и привидения, одни из самых опасных слуг {link:scourge}Плети{/link} в этих землях, и повелитель котла Гнев Души. Ни одна запись не говорит, кем был Гаррон и что сталось с людьми этой фермы.]=],
		},
	},
})

Translate("ruRU", "sorrow-hill", {
	title = "Холм Печали",
	sections = {
		{
			title = "Обзор",
			text = [=[Холм Печали — большое кладбище южных Чумных земель, между Лагерем Промозглого Ветра и {link:ruins-of-andorhal}Андорал{/link}ом. Его склоны покрыты могилами, склепами и памятниками, и среди них стоит гробница, где покоится {link:uther-the-lightbringer}Утер Светоносный{/link}. Мертвые здесь не знают покоя. Скелеты и вурдалаки встают из могил в таком числе, что {link:scourge}Плеть{/link} пользуется холмом как живой стеной перед восточной дорогой в Андорал. Среди надгробий ходит призрак {link:marlene-redpath}Марлен Редпат{/link}: она все еще ищет вестей о племяннице, которую спрятала во время битвы за {link:darrowshire}Дарроушир{/link}.]=],
		},
	},
})

Translate("ruRU", "uther-s-tomb", {
	title = "Гробница Утера",
	sections = {
		{
			title = "Обзор",
			text = [=[Гробница Утера стоит на Холме Печали. Это каменный дом, возведенный в память об {link:uther-the-lightbringer}Утере Светоносном{/link}, первом из паладинов Серебряной Длани. Внутри высится {link:ogres}огр{/link}омная статуя этого паладина. Это одно из немногих мест в Чумных землях, которые все еще удерживают живые. {link:high-priest-thel-danis}Верховный жрец Тел'данис{/link} стережет гробницу и очищает от зла камни мертвых. Здесь же живет старуха {link:myranda-the-hag}Миранда{/link}. Когда-то она была доверенной советницей лорда {link:tirion-fordring}Тириона Фордринга{/link}.]=],
		},
	},
})

Translate("ruRU", "caer-darrow", {
	title = "Каэр Дарроу",
	aliases = { "Озеро Дарроумир" },
	sections = {
		{
			title = "Обзор",
			text = [=[Каэр Дарроу — островной замок на Озере {link:dar}Дар{/link}роумир, на юго-востоке Западных Чумных земель. Многие поколения он был родовым гнездом семьи Баровых и приятным местом, куда знать {link:lordaeron}Лордерона{/link} приезжала отдохнуть у воды. Семья Баровых отдала его {link:cult-of-the-damned}Культу Проклятых{/link}. В склепах под замком культ основал Некроситет, свою школу некромантии. В городке вокруг замка нет живых. Остались его призраки: горожане, стражники, пекарь со своими детьми, художник на берегу. Большинство из них вновь и вновь проживает свой последний счастливый день. Немногие помнят все, и они хотят, чтобы школа была уничтожена.]=],
		},
	},
})

Translate("ruRU", "taelan-fordring", {
	title = "Телан Фордринг",
	subtitle = "Верховный лорд Алого ордена",
	found = "В Крепости Марденхольд, в Дольном Очаге",
	hint = [=[Ищите верховного лорда в крепости Дольного Очага. Орден не жалует чужаков.]=],
	allegiance = "Алый орден",
	aliases = { "Телан", "верховный лорд Телан Фордринг" },
	sections = {
		{
			title = "Обзор",
			text = [=[Телан Фордринг — верховный лорд {link:scarlet-crusade}Алого ордена{/link} в Дольном Очаге. Он командует его рыцарями из Крепости Марденхольд, из дома, где родился. Он сын лорда {link:tirion-fordring}Тириона Фордринга{/link}, который некогда владел этими землями. Телан был мальчиком, когда его отца изгнали, и ему сказали, что отец умер. С тех пор он в это верит.]=],
		},
		{
			title = "Значение",
			text = [=[Телан — последний из рода Фордрингов, кто держит земли своей семьи, и держит он их для ордена, сбившегося с пути. Он был воспитан в {link:holy-light}Свет{/link}е и обучен как паладин Серебряной Длани. Он сражался с {link:scourge}Плетью{/link}, когда пало королевство. Из всех вождей Алого ордена он тот, в ком еще живо что-то от прежнего ордена.]=],
		},
		{
			title = "Ранние годы",
			text = [=[Телан вырос в Крепости Марденхольд, сын лорда {link:tyrion}Тирион{/link}а и его жены Карандры. Когда он был маленьким мальчиком, отец подарил ему небольшой боевой молот, сделанный по образу его собственного. Потом был суд. Тирион пощадил жизнь {link:orcs}орк{/link}а, и за это его лишили земель и титулов и изгнали из ордена. Карандра сказала сыну, что его отец мертв. Телан закопал игрушечный молот на ложной могиле и вырос без отца.]=],
		},
		{
			title = "Падение ордена",
			text = [=[Телан пошел по пути отца и вступил в ряды рыцарей Серебряной Длани. Когда пал {link:uther-the-lightbringer}Утер{/link} и орден был сломлен, он продолжал сражаться рядом с последними его рыцарями. В селении {link:northdale}Северный Дол{/link} он дал последний бой. Там, в отчаянии, он бросил наземь знамя Серебряной Длани и отрекся от ордена. Вместо этого он вступил в {link:scarlet-crusade}Алый орден{/link} и высоко в нем поднялся.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он прошел обучение как паладин Серебряной Длани.
• Он сражался с {link:scourge}Плеть{/link}ю при падении {link:lordaeron}Лордерон{/link}а и дал последний бой в Северном Доле.
• Он отрекся от Серебряной Длани и вступил в {link:scarlet-crusade}Алый орден{/link}.
• Он командует Алым орденом в Дольном Очаге как его верховный лорд.]=],
		},
	},
	chapters = {
		{
			title = "Дар отца",
			hint = [=[Пронесите отцовский дар в Дольный Очаг под видом одного из его защитников.]=],
			text = [=[Гонец пришел в Крепость Марденхольд в гербовой накидке ордена, и Телан принял его за одного из бойцов подкрепления, которого ждали из Длани Тира. Потом он открыл шкатулку. Внутри лежали игрушечный молот с могилы его отца, знамя, которое он бросил в Северном Доле, и картина, где он сам, еще ребенок, изображен на руках у отца и матери на берегу {link:caer-darrow}Каэр Дарроу{/link}. Это не были реликвии мертвеца. Телан упал на одно колено. Он понял, что его отец жив и что ему лгали большую часть его жизни.]=],
		},
		{
			title = "Во снах",
			hint = "Помогите верховному лорду покинуть Дольный Очаг.",
			text = [=[Телан давно видел во снах отца и сражался бок о бок с ним против мертвых. Теперь он решил идти к нему. Он отринул орден, которому так долго служил, и с боем вырвался из Дольного Очага. За стенами орден пустился за ним в погоню. Верховный инквизитор Изиллиен настиг его на дороге и убил на глазах у отца. {link:tyrion}Тирион{/link} опустился на колени над телом сына. Из его горя родилась клятва: Серебряная Длань не мертва, и он возродит ее.]=],
		},
	},
	mentions = {
		{ text = "«О забытых воспоминаниях», игрушечный молот на ложной могиле" },
		{ text = "«Об утраченной чести», знамя Северного Дола" },
		{ text = "«О любви и семье», картина" },
		{ text = "«Найти Миранду»" },
		{ text = "«Алая уловка»" },
		{ text = "«Во снах»" },
	},
	bonds = {
		{ id = "tirion-fordring", name = "Тирион Фордринг", note = "его отец" },
		{ id = "myranda-the-hag", name = "Миранда Карга", note = "советница его отца" },
		{ id = "artist-renfray", name = "художник Ренфрей", note = "написал его ребенком" },
		{ id = "uther-the-lightbringer", name = "Утер Светоносный", note = "возглавлял орден, от которого он отрекся" },
	},
})

Translate("ruRU", "commander-ashlam-valorfist", {
	title = "Командир Ашлам Кулак Доблести",
	subtitle = "Командир Лагеря Промозглого Ветра",
	found = "Лагерь Промозглого Ветра, на юге Западных Чумных земель",
	hint = [=[Поговорите с командиром, который собирает силы Альянса в Лагере Промозглого Ветра.]=],
	allegiance = "Королевство Штормград · Альянс",
	aliases = { "Ашлам Кулак Доблести", "Кулак Доблести" },
	sections = {
		{
			title = "Обзор",
			text = [=[Командир Ашлам Кулак Доблести возглавляет силы {link:alliance}Альянс{/link}а в Западных Чумных землях. Когда {link:stormwind-city}Штормград{/link} разослал свой призыв к оружию против {link:scourge}Плети{/link} севера, добровольцев направляли именно в его лагерь. Это смелый и громогласный человек, охочий до замыслов и до похвалы, и он намерен отбить {link:ruins-of-andorhal}Андорал{/link} у мертвых.]=],
		},
		{
			title = "Значение",
			text = [=[Кулак Доблести — меч {link:alliance}Альянс{/link}а в мертвых землях {link:lordaeron}Лордерона{/link}. Его поход — первая настоящая попытка {link:stormwind-city}Штормград{/link}а ударить по Плети в ее собственном краю с тех пор, как пало королевство.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он построил {link:chillwind-camp}Лагерь Промозглого Ветра{/link} и созвал в него добровольцев от имени {link:stormwind-city}Штормград{/link}а.
• Он замыслил наступление на {link:ruins-of-andorhal}Андорал{/link} по восточной дороге, через {link:sorrow-hill}Холм Печали{/link}.
• Он приказал пометить сторожевые башни Андорала для штурма.
• Он поручил своим жрецам обратить чумные котлы против Плети.
• Он послал защитников искать ключ от Некроситета.]=],
		},
	},
	chapters = {
		{
			title = "Дорога через Холм Печали",
			hint = [=[Очистите от мертвецов холм, что стережет восточную дорогу в Андорал.]=],
			text = [=[Западную и северную дороги в {link:ruins-of-andorhal}Андорал{/link} удерживали слишком крепко. Кулак Доблести выбрал восточную. Чтобы выйти к ней, его силам нужно было миновать {link:sorrow-hill}Холм Печали{/link}, где мертвые сотнями вставали из могил. Первый удар его похода был нанесен среди надгробий.]=],
		},
		{
			title = "Сторожевые башни",
			hint = "Пометьте башни Андорала для штурма.",
			text = [=[{link:scourge}Плеть{/link} пользовалась четырьмя сторожевыми башнями, чтобы направлять свои силы через {link:ruins-of-andorhal}Андорал{/link}. Кулак Доблести велел изготовить сигнальный факел, и с его помощью башни были помечены одна за другой. Его жрецы чувствовали, как ярко горят эти огни. Командир объявил, что пришло время перенести бой в город.]=],
		},
		{
			title = "Котлы",
			hint = [=[Помогите жрецам командира обратить чумные котлы против Плети.]=],
			text = [=[Уничтожить котлы было нельзя. Некромантия, которую творил {link:kel-thuzad}Кел'Тузад{/link}, была слишком сильна. Поэтому помощница командира, верховная жрица {link:high-priestess-macdonnell}МакДоннелл{/link}, задумала изменить то, что в них варится. Все четыре западных котла были вскрыты, образцы их ядов взяты, и было изготовлено противоядие. Когда дело было сделано, командир встал перед своим лагерем и во весь голос возблагодарил защитника, свершившего это, как героя {link:alliance}Альянс{/link}а.]=],
		},
		{
			title = "Увы, Андорал",
			hint = "Уничтожьте лича, который правит Андоралом.",
			text = [=[{link:nak}Нак{/link}онец Кулак Доблести послал своих защитников в сердце {link:ruins-of-andorhal}Андорал{/link}а, против лича {link:araj-the-summoner}Арадж{/link}а Призывателя. Они вернулись с осколком филактерии лича. Командир назвал это победой на века.]=],
		},
	},
	mentions = {
		{ text = "«Призыв к оружию: Чумные земли!»" },
		{ text = "«Расчистить путь»" },
		{ text = "«Вдоль сторожевых башен»" },
		{ text = "«Котлы Плети»" },
		{ text = "«Задание выполнено!»" },
		{ text = "«Некроситет»" },
		{ text = "«Увы, {link:ruins-of-andorhal}Андорал{/link}»" },
		{
			text = [=[«{link:chillwind-point}Берег Промозглого Ветра{/link}», вести от лорда {link:captain-grayson}Грейсон{/link}а Сокрушителя Теней]=],
		},
		{ text = "«Безжизненные камни Плети»" },
		{ text = "«Ковка камня мощи», с перьями троллей затонувшего храма" },
	},
	bonds = {
		{ id = "high-priestess-macdonnell", name = "верховная жрица МакДоннелл", note = "его помощница" },
		{ id = "alchemist-arbington", name = "алхимик Арбингтон", note = "его знаток Некроситета" },
		{ id = "high-priest-thel-danis", name = "верховный жрец Тел'данис", note = "очищает нужные ему камни" },
		{ id = "grayson-shadowbreaker", name = "Грейсон Сокрушитель Теней", note = "присылает ему паладинов" },
		{ id = "high-executor-derrington", name = "верховный исполнитель Деррингтон", note = "командир Орды с той же целью" },
		{ id = "araj-the-summoner", name = "Арадж Призыватель", note = "враг" },
	},
})

Translate("ruRU", "high-executor-derrington", {
	title = "Верховный исполнитель Деррингтон",
	subtitle = "Командир Бастиона",
	found = "Бастион, на восточном краю Тирисфальских лесов",
	hint = "Поговорите с верховным исполнителем, который держит Бастион.",
	allegiance = "Отрекшиеся · Орда",
