		},
		{
			title = "Увы, Андорал",
			hint = "Уничтожьте лича, который правит Андоралом.",
			text = [=[Последним был удар по личу {link:araj-the-summoner}Арадж{/link}у Призывателю. Его защитники принесли осколок филактерии лича, и Деррингтон провозгласил это победой Орды.]=],
		},
	},
	mentions = {
		{ text = "«Призыв к оружию: Чумные земли!»" },
