		{ text = "«Ключ от Некроситета»" },
		{ text = "«Увы, {link:ruins-of-andorhal}Андорал{/link}»" },
	},
	bonds = {
		{ id = "shadow-priestess-vandis", name = "жрица Тьмы Вандис", note = "его помощница" },
