		{ id = "araj-the-summoner", name = "Арадж Призыватель", note = "враг" },
	},
})

Translate("ruRU", "chromie", {
	title = "Хроми",
	subtitle = "Странный историк",
	found = "Разрушенная таверна в северо-западном углу Андорала",
	hint = "Ищите гномку, которая живет в разрушенной таверне Андорала.",
	allegiance = "Неизвестна",
	sections = {
		{
			title = "Обзор",
			text = [=[Хроми — маленькая {link:gnomes}гном{/link}ка, поселившаяся в разрушенной таверне {link:ruins-of-andorhal}Андорал{/link}а, в городе, который держат мертвые. Комната, где она живет, странным образом цела, словно разруха вокруг ее не коснулась. О времени она говорит так, как другие говорят о погоде. Она спрашивает путников, не из будущего ли они, и, похоже, не шутит.]=],
		},
		{
			title = "Значение",
			text = [=[Хроми утверждает, что нечто вмешалось в течение времени в {link:ruins-of-andorhal}Андорал{/link}е и что она пришла это исправить. Кем бы она ни была, о прошлом города и о судьбах тех, кто погиб на войне, она знает куда больше, чем положено {link:gnomes}гном{/link}ке.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она держит комнату в разрушенной таверне {link:ruins-of-andorhal}Андорал{/link}а.
• Она охотится на тварей, что кормятся нарушенным течением времени в городе.
• Она собирает остановившиеся часы Андорала.
• Она стремится узнать судьбу Джозефа {link:marshal-redpath}Редпат{/link}а из {link:darrowshire}Дарроушир{/link}а и изменить ее.]=],
