			text = [=[Хроми сказала, что в ход времени {link:ruins-of-andorhal}Андорал{/link}а кто-то вмешался, и вернее всего — {link:scourge}Плеть{/link}. В амбарах собрались твари, кормящиеся нарушенным временем, и они мешали ее труду. Когда их истребили, она заговорила откровеннее. Она вовсе не {link:gnomes}гном{/link}ка. Она служит бронзовым драконам, хранителям времени, и ее истинный облик скрыт.]=],
		},
		{
			title = "Отсчет времени",
			hint = "Принесите Хроми остановившиеся часы Андорала.",
			text = [=[Чтобы исправить ущерб, нанесенный {link:ruins-of-andorhal}Андорал{/link}у, Хроми трудится из иной нити времени, дабы не потревожить его еще больше. Ей нужны безделушки из того мгновения, когда ударила чума. Часы города годятся, ибо все они остановились в три часа — в час, когда чума начала расходиться. Взамен Хроми дает дары, назначение которых, по ее словам, прояснится со временем.]=],
		},
		{
			title = "Анналы Дарроушира",
			hint = "Найдите летопись Дарроушира в ратуше Андорала.",
			text = [=[Призрак {link:marlene-redpath}Марлен Редпат{/link} послал Хроми кольцо — обручальное кольцо, которое носил {link:joseph-redpath}Джозеф Редпат{/link}. Хроми сразу поняла, что оно принадлежало великому человеку с трагическим прошлым. «Анналы {link:darrowshire}Дарроушир{/link}а», хранившиеся в ратуше {link:ruins-of-andorhal}Андорал{/link}а, поведали остальное: в битве за Дарроушир Джозеф был осквернен и обращен против его защитников. Хроми решила изменить эту судьбу, если сумеет.]=],
		},
	},
	mentions = {
