			title = "Значение",
			text = [=[Арадж некогда возглавлял Некроситет, школу некромантии культа под {link:caer-darrow}Каэр Дарроу{/link}, прежде чем забрал {link:ruins-of-andorhal}Андорал{/link} себе. Его печать, скарабей, — одна из немногих вещей, способных отворить запечатанную дверь школы.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он возглавлял Некроситет до того, как взял {link:ruins-of-andorhal}Андорал{/link}.
• Он правит Руинами Андорала от имени Плети.
• Его скарабей — головка ключа от Некроситета.]=],
		},
	},
	chapters = {
		{
