			hint = "Уничтожьте лича Андорала.",
			text = [=[Защитники и {link:alliance}Альянс{/link}а, и Орды ворвались в сердце {link:ruins-of-andorhal}Андорал{/link}а и прорубились сквозь стражу лича. Они сокрушили его филактерию, и осколок ее отправился в {link:chillwind-camp}Лагерь Промозглого Ветра{/link} и в {link:the-bulwark}Бастион{/link} как доказательство.]=],
		},
	},
	mentions = {
		{ text = "«Увы, {link:ruins-of-andorhal}Андорал{/link}»" },
		{ text = "«Скарабей лича Араджа»" },
