	chapters = {
		{
			title = "Последний из рода",
			hint = [=[Выслушайте, как дворянин из Лагеря Промозглого Ветра хочет поступить со своим братом.]=],
			text = [=[Когда грамоты на {link:caer-darrow}Каэр Дарроу{/link}, {link:brill}Брилл{/link}, {link:tarren-mill}Мельницу Таррен{/link} и {link:southshore}Южнобережье{/link} оказались у него в руках, Велдон пожелал еще одного. Он пожелал голову своего брата, принесенную ему из {link:the-bulwark}Бастион{/link}а. Сам он на такое не пошел бы. Подобные дела, сказал он, ниже человека его происхождения.]=],
